"""One inference implementation for CLI and benchmark-only MCP."""

import importlib.util
import math
import platform
import threading
import time
from collections import Counter

from .config import MODELS, checkpoint
from .presets import OPTIONS, SAFE_COMMANDS, deterministic_choice, hard_risk


class Unavailable(Exception):
    """Operational failure safe to expose without request contents."""


def finite(value):
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError("JSON numbers must be finite")
    if isinstance(value, dict):
        for item in value.values():
            finite(item)
    elif isinstance(value, list):
        for item in value:
            finite(item)


def validate(request):
    if not isinstance(request, dict):
        raise ValueError("request must be an object")
    if request.keys() - {"id", "state", "questions", "preset", "model", "min_confidence"}:
        raise ValueError("unknown request field")
    state = request.get("state")
    if not isinstance(state, (str, dict, list)):
        raise ValueError("state must be text, an object, or a conversation list")
    finite(request)
    if "id" in request and (type(request["id"]) not in (str, int) or len(str(request["id"])) > 128):
        raise ValueError("id must be a string or integer of at most 128 characters")
    if not isinstance(request.get("model", "auto"), str) or request.get("model", "auto") not in {"auto", *MODELS}:
        raise ValueError("model must be auto, english, multilingual, or typed-decisions")
    threshold = request.get("min_confidence")
    if threshold is not None and (type(threshold) not in (int, float) or not 0 <= threshold <= 1):
        raise ValueError("min_confidence must be between zero and one")
    if ("preset" in request) == ("questions" in request):
        raise ValueError("provide exactly one of preset or questions")
    if "preset" in request:
        if not isinstance(request["preset"], str) or request["preset"] not in OPTIONS or not isinstance(state, dict):
            raise ValueError("preset must name a supported policy and state must be an object")
        if "action" in state and not isinstance(state["action"], str):
            raise ValueError("action must be text")
        return
    questions = request["questions"]
    if not isinstance(questions, dict) or not 1 <= len(questions) <= 64:
        raise ValueError("questions must contain between one and 64 definitions")
    for key, question in questions.items():
        if not isinstance(key, str) or not key.strip() or not isinstance(question, dict):
            raise ValueError("each question needs a nonempty string id and an object definition")
        kind = question.get("type")
        if not isinstance(kind, str) or kind not in {"choice", "score", "noul"}:
            raise ValueError("question type must be choice, score, or noul")
        if not isinstance(question.get("instructions"), str) or not question["instructions"].strip():
            raise ValueError("question instructions must be nonempty text")
        criteria = question.get("criteria")
        if kind in {"choice", "score"}:
            if not isinstance(criteria, (dict, list)) or not 2 <= len(criteria) <= 64:
                raise ValueError("choice and score need between two and 64 criteria")
            if kind == "score" and not isinstance(criteria, list):
                raise ValueError("score criteria must be an ordered list")
            labels = list(criteria)
            if any(not isinstance(label, str) or not label.strip() for label in labels):
                raise ValueError("criteria must have nonempty text labels")
            if len(set(labels)) != len(labels):
                raise ValueError("criteria labels must be unique")
            if isinstance(criteria, dict) and any(not isinstance(v, str) for v in criteria.values()):
                raise ValueError("choice definitions must be text")
        elif criteria is not None and (
            not isinstance(criteria, dict) or set(criteria) != {"false", "true"}
            or any(not isinstance(v, str) for v in criteria.values())
        ):
            raise ValueError("noul criteria must define false and true")


class Runtime:
    def __init__(self):
        self.router = None
        self.loaded = None
        self.loading = False
        self.error = None
        self.load_count = 0
        self.load_ms = None

    def load(self, name):
        if platform.system() != "Darwin" or platform.machine() != "arm64":
            self.error = "unsupported_platform"
            raise Unavailable("unsupported_platform")
        if importlib.util.find_spec("laya_mlx") is None:
            self.error = "mlx_extra_missing"
            raise Unavailable("mlx_extra_missing")
        if self.loaded == name:
            return self.router.load(name)
        self.loading = True
        start = time.perf_counter()
        try:
            import laya_mlx

            if self.router is None:
                self.router = laya_mlx.Router(max_loaded=1)
            try:
                path = checkpoint(name)
            except Exception as exc:
                raise Unavailable("checkpoint_not_cached") from exc
            self.router.models[name] = str(path)
            agent = self.router.load(name)
            self.loaded = name
            self.load_count += 1
            self.error = None
            return agent
        except Unavailable as exc:
            self.error = str(exc)
            raise
        except Exception as exc:
            self.error = "model_load_failed"
            raise Unavailable(self.error) from exc
        finally:
import copy
import json
import os
import subprocess
import sys
import tempfile
import time
import unittest
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from unittest.mock import patch

from cam_laya_cli.engine import Engine, Runtime, Unavailable, validate
from cam_laya_cli.integrations import install, uninstall
from cam_laya_cli.presets import hard_risk
from cam_laya_cli.worker import MAX_BYTES, Client, parse, request

ROOT = Path(__file__).resolve().parents[1]
QUESTION = {"state": "Example", "questions": {
    "q": {"type": "choice", "instructions": "Choose.", "criteria": ["alpha", "beta"]}}}


class FakeAgent:
    def __init__(self, usage=None, confidence=.8):
        self.usage = usage or {"truncated_questions": []}
        self.confidence = confidence

    def predict(self, state, questions):
        answers = {}
        for key, question in questions.items():
            kind = question["type"]
            answers[key] = {"type": kind, "confidence": self.confidence,
                            "answer_confidence": self.confidence,
                            {"choice": "choice", "score": "score", "noul": "noul"}[kind]:
                            list(question["criteria"])[0] if kind == "choice" else .75}
        return {"answers": answers, "usage": self.usage}


class FakeRuntime:
    def __init__(self, agent=None, unavailable=False, uncalibrated=False):
        self.agent = agent or FakeAgent()
        self.unavailable = unavailable
        self.bad_temperature = uncalibrated
        self.calls = 0

    def route(self, *_):
        return "english"

    def load(self, *_):
        if self.unavailable:
            raise Unavailable("checkpoint_not_cached")
        self.calls += 1
        return self.agent

    def uncalibrated(self, *_):
        return self.bad_temperature


class Decisions(unittest.TestCase):
    def test_guard_corpus_and_legacy_choices(self):
        cases = json.loads((ROOT / "benchmarks/guard_cases.json").read_text())["cases"]
        self.assertEqual(len(cases), 299)
        for case in cases:
            with self.subTest(case=case["id"]):
                self.assertEqual(bool(hard_risk(case["action"])), case["expect"] == "block")
        runtime = FakeRuntime(unavailable=True)
        engine = Engine(runtime)
        for case in json.loads((ROOT / "benchmarks/decision_cases.json").read_text()):
            result = engine.decide({"preset": case["policy"], "state": case["state"]})
            self.assertEqual(result["decision"], case["expected"])
            self.assertEqual(result["source"], "rule")
        self.assertEqual(runtime.calls, 0)

    def test_custom_types_and_abstention(self):
        value = copy.deepcopy(QUESTION)
        value["questions"].update({
            "score": {"type": "score", "instructions": "Rate.", "criteria": ["low", "high"]},
            "boolean": {"type": "noul", "instructions": "Is relevant?"}})
        result = Engine(FakeRuntime()).decide(value)
        self.assertEqual(result["status"], "ok")
        self.assertEqual(result["answers"]["boolean"]["value"], .75)
        self.assertEqual(result["answers"]["q"]["abstention"], "unevaluated")
        value["min_confidence"] = .9
        result = Engine(FakeRuntime()).decide(value)
        self.assertEqual(result["status"], "abstained")
        self.assertIsNone(result["answers"]["q"]["value"])
        self.assertEqual(result["answers"]["q"]["reason_code"], "low_confidence")

    def test_diagnostics_abstain_and_unavailable_never_authorizes(self):
        variants = [(FakeRuntime(FakeAgent({"truncated_questions": ["q"]})), "truncated_state"),
                    (FakeRuntime(FakeAgent({"options": {"q": {}}})), "collapsed_options"),
                    (FakeRuntime(uncalibrated=True), "uncalibrated_temperature")]
        for runtime, reason in variants:
            result = Engine(runtime).decide(QUESTION)
            self.assertEqual(result["answers"]["q"]["reason_code"], reason)
        result = Engine(FakeRuntime(unavailable=True)).decide({
            "preset": "risk_check", "state": {"action": "custom-operation"}})
        self.assertEqual(result["status"], "unavailable")
        self.assertTrue(result["requires_human"])
        result = Engine(FakeRuntime()).decide({"preset": "risk_check", "state": {"action": "custom-operation"}})
        self.assertTrue(result["requires_human"])

    def test_input_boundaries(self):
        for raw in [b'{"a":1,"a":2}', b'{"x":NaN}', b'{"x":Infinity}', b'x' * (MAX_BYTES + 1)]:
            with self.assertRaises(ValueError):
                parse(raw)
        for field, bad in [("model", []), ("min_confidence", float("nan")), ("state", None)]:
            value = {**QUESTION, field: bad}
            with self.assertRaises(ValueError):
                validate(value)
        value = copy.deepcopy(QUESTION)
        value["questions"]["q"]["criteria"] = ["same", "same"]
        with self.assertRaises(ValueError):
            validate(value)
        self.assertEqual(parse('{"state":"Xin chào"}'.encode())["state"], "Xin chào")

    def test_invalid_model_output_and_temperature_gate(self):
        runtime = FakeRuntime(FakeAgent(confidence=float("nan")))
        self.assertEqual(Engine(runtime).decide(QUESTION)["status"], "unavailable")
        agent = FakeAgent()
        with patch.object(agent, "predict", return_value={"answers": {}, "usage": {}}):
            self.assertEqual(Engine(FakeRuntime(agent)).decide(QUESTION)["status"], "unavailable")
        # Validate the native temperature adapter without requiring MLX in base installs.
        import types

        module = types.ModuleType("laya_mlx.common")
        module.QTYPES = {"choice": 0, "score": 1, "noul": 2}
        module.temp_bucket = lambda kind, count: "choice:11+" if count >= 11 else "choice:2"
        agent = types.SimpleNamespace(temperature_by_options_raw={"choice:11+": .1},
                                      temperature_by_options={"choice:11+": .5},
                                      temperature_raw=[1., 1., 1.], temperature=[1., 1., 1.])
        with patch.dict(sys.modules, {"laya_mlx.common": module}):
            self.assertTrue(Runtime().uncalibrated(agent, "choice", 12))
            self.assertFalse(Runtime().uncalibrated(agent, "choice", 2))
